insert into public.item_translations (item_id, locale, name, description, description_long, ingredients)
select i.id, v.locale, v.name, v.description, v.description_long, v.ingredients
from (values
  ('hvitloksbrod', 'nb', 'Hvitløksbrød', 'Sprøtt surdeigsbrød med hvitløkssmør', 'Surdeigsbrød bakt samme morgen, penslet med hvitløkssmør og persille og stekt til kantene er sprø. Serveres varmt.', 'Surdeigsbrød, smør, hvitløk, persille, havsalt'),
  ('hvitloksbrod', 'en', 'Garlic bread', 'Crisp sourdough with garlic butter', 'Sourdough baked the same morning, brushed with garlic butter and parsley and grilled until the edges crisp. Served warm.', 'Sourdough bread, butter, garlic, parsley, sea salt'),
  ('hvitloksbrod', 'it', 'Pane all''aglio', 'Pane a lievitazione naturale con burro all''aglio', 'Pane a lievitazione naturale sfornato la mattina stessa, spennellato con burro all''aglio e prezzemolo e gratinato finché i bordi diventano croccanti. Servito caldo.', 'Pane a lievitazione naturale, burro, aglio, prezzemolo, sale marino'),
  ('hvitloksbrod', 'zh-CN', '蒜香面包', '酥脆酸面包配蒜香黄油', '当天早晨烘焙的酸面包，刷上蒜香黄油和欧芹，烤至边缘酥脆。热食。', '酸面包、黄油、大蒜、欧芹、海盐'),
  ('tomatsuppe', 'nb', 'Tomatsuppe', 'Ovnsbakte tomater, basilikum, creme fraiche', 'Tomater bakt sakte i ovnen med hvitløk og timian, kjørt glatt og rørt ut med en skje creme fraiche. Basilikum på toppen.', 'Tomat, løk, hvitløk, timian, creme fraiche, basilikum, olivenolje'),
  ('tomatsuppe', 'en', 'Tomato soup', 'Oven-roasted tomatoes, basil, crème fraîche', 'Tomatoes slow-roasted with garlic and thyme, blended smooth and finished with a spoon of crème fraîche. Basil on top.', 'Tomato, onion, garlic, thyme, crème fraîche, basil, olive oil'),
  ('tomatsuppe', 'it', 'Zuppa di pomodoro', 'Pomodori al forno, basilico, crème fraîche', 'Pomodori arrostiti lentamente con aglio e timo, frullati fino a crema e completati con un cucchiaio di crème fraîche. Basilico in superficie.', 'Pomodoro, cipolla, aglio, timo, crème fraîche, basilico, olio d''oliva'),
  ('tomatsuppe', 'zh-CN', '番茄汤', '烤番茄、罗勒、法式酸奶油', '番茄与大蒜、百里香慢烤，打成顺滑浓汤，最后加入一勺法式酸奶油。顶部点缀罗勒。', '番茄、洋葱、大蒜、百里香、法式酸奶油、罗勒、橄榄油'),
  ('bruschetta', 'nb', 'Bruschetta', 'Tomat, basilikum og olivenolje på ristet brød', 'Ristet surdeigsbrød gnidd med rå hvitløk, toppet med modne tomater, basilikum og god olivenolje. Enkelt og sommerlig.', 'Surdeigsbrød, tomat, hvitløk, basilikum, olivenolje, havsalt'),
  ('bruschetta', 'en', 'Bruschetta', 'Tomato, basil and olive oil on toasted bread', 'Toasted sourdough rubbed with raw garlic, piled with ripe tomatoes, basil and good olive oil. Simple and summery.', 'Sourdough bread, tomato, garlic, basil, olive oil, sea salt'),
  ('bruschetta', 'it', 'Bruschetta', 'Pomodoro, basilico e olio d''oliva su pane tostato', 'Pane a lievitazione naturale tostato e strofinato con aglio crudo, con pomodori maturi, basilico e buon olio d''oliva. Semplice ed estiva.', 'Pane a lievitazione naturale, pomodoro, aglio, basilico, olio d''oliva, sale marino'),
  ('bruschetta', 'zh-CN', '意式烤面包', '番茄、罗勒与橄榄油配烤面包', '酸面包烤香后抹上生蒜，铺满熟番茄、罗勒和优质橄榄油。简单而清爽。', '酸面包、番茄、大蒜、罗勒、橄榄油、海盐'),
  ('kyllingvinger', 'nb', 'Kyllingvinger', 'Sterk glasur, sesam, syltet rødløk', 'Vinger marinert over natten, stekt sprø og vendt i en sterk glasur av chili og honning. Sesamfrø og syltet rødløk til.', 'Kylling, chili, honning, soyasaus, hvitløk, sesamfrø, rødløk, eddik'),
  ('kyllingvinger', 'en', 'Chicken wings', 'Hot glaze, sesame, pickled red onion', 'Wings marinated overnight, fried crisp and tossed in a hot chilli-and-honey glaze. Sesame seeds and pickled red onion alongside.', 'Chicken, chilli, honey, soy sauce, garlic, sesame seeds, red onion, vinegar'),
  ('kyllingvinger', 'it', 'Ali di pollo', 'Glassa piccante, sesamo, cipolla rossa marinata', 'Ali marinate per una notte, fritte croccanti e saltate in una glassa piccante di peperoncino e miele. Con semi di sesamo e cipolla rossa marinata.', 'Pollo, peperoncino, miele, salsa di soia, aglio, semi di sesamo, cipolla rossa, aceto'),
  ('kyllingvinger', 'zh-CN', '烤鸡翅', '香辣蜜汁、芝麻、腌红洋葱', '鸡翅隔夜腌制，炸至酥脆，再裹上辣椒蜂蜜酱。配芝麻与腌红洋葱。', '鸡肉、辣椒、蜂蜜、酱油、大蒜、芝麻、红洋葱、醋'),
  ('mozzarellasticks', 'nb', 'Mozzarellasticks', 'Panert mozzarella med tomatdip', 'Mozzarella panert i krydret brødsmuler og fritert til osten så vidt trekker seg. Serveres med en kald tomatdip.', 'Mozzarella, brødsmuler, egg, hvetemel, oregano, tomat, hvitløk'),
  ('mozzarellasticks', 'en', 'Mozzarella sticks', 'Breaded mozzarella with tomato dip', 'Mozzarella in seasoned breadcrumbs, fried until the cheese just pulls. Served with a cold tomato dip.', 'Mozzarella, breadcrumbs, egg, wheat flour, oregano, tomato, garlic'),
  ('mozzarellasticks', 'it', 'Bastoncini di mozzarella', 'Mozzarella impanata con salsa al pomodoro', 'Mozzarella impanata con pangrattato aromatizzato e fritta finché il formaggio comincia a filare. Servita con una salsa fredda al pomodoro.', 'Mozzarella, pangrattato, uova, farina di grano, origano, pomodoro, aglio'),
  ('mozzarellasticks', 'zh-CN', '炸马苏里拉条', '面包糠马苏里拉配番茄酱', '马苏里拉裹上调味面包糠炸至芝士恰好拉丝。配冷番茄蘸酱。', '马苏里拉、面包糠、鸡蛋、小麦粉、牛至、番茄、大蒜'),
  ('rekecocktail', 'nb', 'Rekecocktail', 'Håndpillede reker, sitron, rosasaus', 'Håndpillede reker fra Nordsjøen på knasende salat, med en klassisk rosasaus og rikelig med sitron.', 'Reker, salat, majones, tomatpuré, sitron, dill, pepper'),
  ('rekecocktail', 'en', 'Prawn cocktail', 'Hand-peeled prawns, lemon, cocktail sauce', 'Hand-peeled North Sea prawns on crisp lettuce, with a classic cocktail sauce and plenty of lemon.', 'Prawns, lettuce, mayonnaise, tomato purée, lemon, dill, pepper'),
  ('rekecocktail', 'it', 'Cocktail di gamberi', 'Gamberi sgusciati, limone, salsa rosa', 'Gamberi del Mare del Nord sgusciati a mano su lattuga croccante, con una classica salsa rosa e abbondante limone.', 'Gamberi, lattuga, maionese, concentrato di pomodoro, limone, aneto, pepe'),
  ('rekecocktail', 'zh-CN', '鲜虾杯', '手剥鲜虾、柠檬、鸡尾酒酱', '手剥北海鲜虾配脆生菜，佐以经典鸡尾酒酱和充足的柠檬。', '虾、生菜、蛋黄酱、番茄泥、柠檬、莳萝、胡椒'),
  ('hummus-flatbrod', 'nb', 'Hummus med flatbrød', 'Kremet kikertpuré, olivenolje, varmt brød', 'Kikerter kokt møre og kjørt glatt med tahini, sitron og hvitløk. Olivenolje og sumak på toppen, varmt flatbrød ved siden av.', 'Kikerter, tahini, sitron, hvitløk, olivenolje, sumak, flatbrød'),
