  ('tunfisksalat', 'zh-CN', '金枪鱼沙拉', '金枪鱼、鸡蛋、橄榄、脆豆角', '橄榄油浸金枪鱼配水煮蛋、脆豆角、小土豆和橄榄。大致是尼斯沙拉的做法。', '金枪鱼、鸡蛋、四季豆、小土豆、橄榄、生菜、柠檬、橄榄油'),
  ('bete-geitost', 'nb', 'Rødbete og geitost', 'Ovnsbakte rødbeter, geitost, valnøtter', 'Rødbeter bakt hele i ovnen, med myk geitost, ristede valnøtter, honning og ruccola.', 'Rødbete, geitost, valnøtter, honning, ruccola, balsamicoeddik, olivenolje'),
  ('bete-geitost', 'en', 'Beetroot and goat cheese', 'Roast beetroot, goat cheese, walnuts', 'Beetroots roasted whole, with soft goat cheese, toasted walnuts, honey and rocket.', 'Beetroot, goat cheese, walnuts, honey, rocket, balsamic vinegar, olive oil'),
  ('bete-geitost', 'it', 'Barbabietola e caprino', 'Barbabietola al forno, caprino, noci', 'Barbabietole arrostite intere, con caprino morbido, noci tostate, miele e rucola.', 'Barbabietola, caprino, noci, miele, rucola, aceto balsamico, olio d''oliva'),
  ('bete-geitost', 'zh-CN', '甜菜根山羊奶酪', '烤甜菜根、山羊奶酪、核桃', '整颗甜菜根烘烤后，配软质山羊奶酪、烤核桃、蜂蜜和芝麻菜。', '甜菜根、山羊奶酪、核桃、蜂蜜、芝麻菜、意大利香醋、橄榄油'),
  ('sjokoladefondant', 'nb', 'Sjokoladefondant', 'Varm sjokoladekake med flytende kjerne', 'Bakes når du bestiller, så regn med tolv minutter. Mørk sjokolade med flytende kjerne, vaniljeis ved siden av.', 'Mørk sjokolade, smør, egg, sukker, hvetemel, vaniljeis'),
  ('sjokoladefondant', 'en', 'Chocolate fondant', 'Warm chocolate cake with a molten centre', 'Baked when you order it, so allow twelve minutes. Dark chocolate with a molten centre and vanilla ice cream alongside.', 'Dark chocolate, butter, egg, sugar, wheat flour, vanilla ice cream'),
  ('sjokoladefondant', 'it', 'Tortino al cioccolato', 'Tortino caldo dal cuore morbido', 'Preparato al momento dell''ordine, quindi serve una dozzina di minuti. Cioccolato fondente dal cuore morbido e gelato alla vaniglia.', 'Cioccolato fondente, burro, uova, zucchero, farina di grano, gelato alla vaniglia'),
  ('sjokoladefondant', 'zh-CN', '熔岩巧克力蛋糕', '温热巧克力蛋糕，内馅流心', '点单后现烤，请预留十二分钟。黑巧克力蛋糕带流心内馅，配香草冰淇淋。', '黑巧克力、黄油、鸡蛋、糖、小麦粉、香草冰淇淋'),
  ('ostekake', 'nb', 'Ostekake', 'New York-ostekake med bærkompott', 'Tett og kremet ostekake på smørkjeksbunn, med en kompott av norske skogsbær og litt revet sitronskall.', 'Kremost, fløte, egg, sukker, smørkjeks, smør, blåbær, bringebær, sitron'),
  ('ostekake', 'en', 'Cheesecake', 'New York cheesecake with berry compote', 'Dense, creamy cheesecake on a biscuit base, with a compote of Norwegian forest berries and a little lemon zest.', 'Cream cheese, cream, egg, sugar, biscuit, butter, blueberry, raspberry, lemon'),
  ('ostekake', 'it', 'Cheesecake', 'Cheesecake newyorkese con composta di frutti di bosco', 'Cheesecake densa e cremosa su base di biscotto, con una composta di frutti di bosco norvegesi e un po'' di scorza di limone.', 'Formaggio spalmabile, panna, uova, zucchero, biscotto, burro, mirtillo, lampone, limone'),
  ('ostekake', 'zh-CN', '芝士蛋糕', '纽约芝士蛋糕配莓果酱', '绵密浓郁的芝士蛋糕，饼干底，佐挪威森林莓果酱和少许柠檬皮。', '奶油芝士、奶油、鸡蛋、糖、饼干、黄油、蓝莓、树莓、柠檬'),
  ('tiramisu', 'nb', 'Tiramisu', 'Mascarpone, espresso, kakao', 'Lady fingers dyppet i espresso, lagvis med mascarponekrem og kakao på toppen. Laget dagen før, som den skal.', 'Mascarpone, egg, sukker, espresso, lady fingers, kakao, marsala'),
  ('tiramisu', 'en', 'Tiramisu', 'Mascarpone, espresso, cocoa', 'Ladyfingers dipped in espresso, layered with mascarpone cream and dusted with cocoa. Made the day before, as it should be.', 'Mascarpone, egg, sugar, espresso, ladyfingers, cocoa, marsala'),
  ('tiramisu', 'it', 'Tiramisù', 'Mascarpone, espresso, cacao', 'Savoiardi inzuppati nell''espresso, a strati con crema al mascarpone e cacao in superficie. Preparato il giorno prima, come si deve.', 'Mascarpone, uova, zucchero, espresso, savoiardi, cacao, marsala'),
  ('tiramisu', 'zh-CN', '提拉米苏', '马斯卡彭、浓缩咖啡、可可', '手指饼干浸浓缩咖啡，与马斯卡彭奶油层叠，撒上可可粉。按传统提前一天制作。', '马斯卡彭、鸡蛋、糖、浓缩咖啡、手指饼干、可可、马沙拉酒'),
  ('eplekake', 'nb', 'Eplekake', 'Varm eplekake med vaniljesaus', 'Norske epler bakt i en lett kanelkake, servert varm med vaniljesaus. Husets mest bestilte dessert om høsten.', 'Epler, hvetemel, smør, egg, sukker, kanel, melk, vanilje'),
  ('eplekake', 'en', 'Apple cake', 'Warm apple cake with vanilla sauce', 'Norwegian apples baked into a light cinnamon cake, served warm with vanilla sauce. The most ordered dessert here in autumn.', 'Apples, wheat flour, butter, egg, sugar, cinnamon, milk, vanilla'),
  ('eplekake', 'it', 'Torta di mele', 'Torta di mele calda con salsa alla vaniglia', 'Mele norvegesi cotte in una torta leggera alla cannella, servita calda con salsa alla vaniglia. Il dolce più ordinato qui in autunno.', 'Mele, farina di grano, burro, uova, zucchero, cannella, latte, vaniglia'),
  ('eplekake', 'zh-CN', '苹果蛋糕', '温热苹果蛋糕配香草酱', '挪威苹果烤入轻盈的肉桂蛋糕，温热上桌并佐香草酱。秋天这里点得最多的甜品。', '苹果、小麦粉、黄油、鸡蛋、糖、肉桂、牛奶、香草'),
  ('riskrem', 'nb', 'Riskrem', 'Kald riskrem med rød saus og mandel', 'Kald riskrem rørt med vaniljesukker og pisket fløte, med varm rød bærsaus og en hel mandel i porsjonen.', 'Ris, melk, fløte, sukker, vanilje, mandel, bringebær'),
  ('riskrem', 'en', 'Riskrem', 'Cold rice cream with berry sauce and almond', 'Cold rice cream folded with vanilla sugar and whipped cream, with a warm red berry sauce and one whole almond in the portion.', 'Rice, milk, cream, sugar, vanilla, almond, raspberry'),
  ('riskrem', 'it', 'Riskrem', 'Crema di riso fredda con salsa ai frutti rossi e mandorla', 'Crema di riso fredda montata con zucchero vanigliato e panna, con salsa calda ai frutti rossi e una mandorla intera nella porzione.', 'Riso, latte, panna, zucchero, vaniglia, mandorla, lampone'),
  ('riskrem', 'zh-CN', '挪威米布丁', '冰凉米布丁配莓果酱与杏仁', '冰凉米布丁拌入香草糖和打发奶油，配温热红莓果酱，每份里藏有一颗完整杏仁。', '大米、牛奶、奶油、糖、香草、杏仁、树莓'),
  ('isdessert', 'nb', 'Tre kuler is', 'Vanilje, sjokolade eller jordbær', 'Tre kuler hjemmelaget is — vanilje, mørk sjokolade eller jordbær — med pisket krem og en kjeks.', 'Melk, fløte, egg, sukker, vanilje, sjokolade, jordbær'),
  ('isdessert', 'en', 'Three scoops of ice cream', 'Vanilla, chocolate or strawberry', 'Three scoops of ice cream made here — vanilla, dark chocolate or strawberry — with whipped cream and a biscuit.', 'Milk, cream, egg, sugar, vanilla, chocolate, strawberry'),
  ('isdessert', 'it', 'Tre palline di gelato', 'Vaniglia, cioccolato o fragola', 'Tre palline di gelato fatto in casa — vaniglia, cioccolato fondente o fragola — con panna montata e un biscotto.', 'Latte, panna, uova, zucchero, vaniglia, cioccolato, fragola'),
  ('isdessert', 'zh-CN', '三球冰淇淋', '香草、巧克力或草莓', '三球自制冰淇淋——香草、黑巧克力或草莓——配打发奶油和一块饼干。', '牛奶、奶油、鸡蛋、糖、香草、巧克力、草莓'),
  ('creme-brulee', 'nb', 'Crème brûlée', 'Vaniljekrem med brent sukkerlokk', 'Vaniljekrem bakt i vannbad og kjølt, med et lokk av sukker brent hardt rett før servering så det knekker.', 'Fløte, eggeplomme, sukker, vaniljestang'),
  ('creme-brulee', 'en', 'Crème brûlée', 'Vanilla custard under burnt sugar', 'Vanilla custard baked in a water bath and chilled, with a lid of sugar burnt hard just before serving so it cracks.', 'Cream, egg yolk, sugar, vanilla pod'),
  ('creme-brulee', 'it', 'Crème brûlée', 'Crema alla vaniglia sotto zucchero bruciato', 'Crema alla vaniglia cotta a bagnomaria e raffreddata, con una crosta di zucchero bruciata poco prima di servire perché si rompa.', 'Panna, tuorlo d''uovo, zucchero, baccello di vaniglia'),
  ('creme-brulee', 'zh-CN', '法式焦糖布丁', '香草蛋奶冻配焦糖脆面', '香草蛋奶冻水浴烘烤后冷藏，上桌前现烤一层硬糖壳，敲开即裂。', '奶油、蛋黄、糖、香草荚'),
  ('brownie', 'nb', 'Brownie', 'Seig sjokoladebrownie med pekannøtter', 'Seig brownie på mørk sjokolade med pekannøtter, servert lun med en kule vaniljeis.', 'Mørk sjokolade, smør, egg, sukker, hvetemel, pekannøtter, vaniljeis'),
  ('brownie', 'en', 'Brownie', 'Fudgy chocolate brownie with pecans', 'A fudgy dark chocolate brownie with pecans, served warm with a scoop of vanilla ice cream.', 'Dark chocolate, butter, egg, sugar, wheat flour, pecans, vanilla ice cream'),
  ('brownie', 'it', 'Brownie', 'Brownie al cioccolato con noci pecan', 'Un brownie denso al cioccolato fondente con noci pecan, servito tiepido con una pallina di gelato alla vaniglia.', 'Cioccolato fondente, burro, uova, zucchero, farina di grano, noci pecan, gelato alla vaniglia'),
  ('brownie', 'zh-CN', '布朗尼', '浓郁巧克力布朗尼配碧根果', '湿润浓郁的黑巧克力布朗尼配碧根果，温热上桌并佐一球香草冰淇淋。', '黑巧克力、黄油、鸡蛋、糖、小麦粉、碧根果、香草冰淇淋'),
  ('kaffe', 'nb', 'Kaffe', 'Espresso, americano eller filterkaffe', 'Bønner brent i Oslo, malt når du bestiller. Espresso, americano eller filterkaffe — melk på forespørsel.', 'Kaffebønner, vann'),
  ('kaffe', 'en', 'Coffee', 'Espresso, americano or filter', 'Beans roasted in Oslo, ground when you order. Espresso, americano or filter — milk on request.', 'Coffee beans, water'),
  ('kaffe', 'it', 'Caffè', 'Espresso, americano o filtro', 'Chicchi tostati a Oslo, macinati al momento dell''ordine. Espresso, americano o filtro — latte su richiesta.', 'Chicchi di caffè, acqua'),
  ('kaffe', 'zh-CN', '咖啡', '浓缩、美式或滴滤', '奥斯陆本地烘焙的咖啡豆，点单后现磨。浓缩、美式或滴滤——需要牛奶请告知。', '咖啡豆、水'),
  ('te', 'nb', 'Te', 'Svart, grønn, mynte eller kamille', 'Løsvekt-te trukket ved bordet. Svart, grønn, fersk mynte eller kamille — spør om dagens utvalg.', 'Teblader, vann, fersk mynte'),
  ('te', 'en', 'Tea', 'Black, green, mint or chamomile', 'Loose-leaf tea brewed at the table. Black, green, fresh mint or chamomile — ask what''s in today.', 'Tea leaves, water, fresh mint'),
  ('te', 'it', 'Tè', 'Nero, verde, menta o camomilla', 'Tè in foglia preparato al tavolo. Nero, verde, menta fresca o camomilla — chiedi la selezione del giorno.', 'Foglie di tè, acqua, menta fresca'),
  ('te', 'zh-CN', '茶', '红茶、绿茶、薄荷或洋甘菊', '散叶茶现泡上桌。红茶、绿茶、鲜薄荷或洋甘菊——今天有哪些请询问我们。', '茶叶、水、鲜薄荷'),
  ('appelsinjuice', 'nb', 'Appelsinjuice', 'Nypresset, uten tilsatt sukker', 'Presset på appelsiner når du bestiller. Ingenting tilsatt — verken sukker eller vann.', 'Appelsin'),
  ('appelsinjuice', 'en', 'Orange juice', 'Freshly squeezed, no added sugar', 'Squeezed from oranges when you order. Nothing added — no sugar, no water.', 'Orange'),
  ('appelsinjuice', 'it', 'Succo d''arancia', 'Spremuto al momento, senza zuccheri aggiunti', 'Spremuto dalle arance al momento dell''ordine. Niente di aggiunto — né zucchero né acqua.', 'Arancia'),
  ('appelsinjuice', 'zh-CN', '鲜榨橙汁', '现榨，不加糖', '点单后现榨橙子。不添加任何东西——不加糖，不加水。', '橙子'),
  ('brus', 'nb', 'Brus', 'Cola, appelsin eller sitron', 'Cola, appelsinbrus eller sitronbrus på flaske, servert kaldt med is og sitron.', 'Brus, is, sitron'),
  ('brus', 'en', 'Soft drink', 'Cola, orange or lemon', 'Cola, orangeade or lemonade by the bottle, served cold with ice and lemon.', 'Soft drink, ice, lemon'),
  ('brus', 'it', 'Bibita', 'Cola, arancia o limone', 'Cola, aranciata o limonata in bottiglia, servite fredde con ghiaccio e limone.', 'Bibita, ghiaccio, limone'),
  ('brus', 'zh-CN', '汽水', '可乐、橙味或柠檬味', '瓶装可乐、橙味或柠檬汽水，冰镇上桌，配冰块和柠檬。', '汽水、冰、柠檬'),
  ('farris', 'nb', 'Mineralvann', 'Med eller uten kullsyre', 'Norsk mineralvann med eller uten kullsyre, servert kaldt med is og sitron.', 'Mineralvann, is, sitron'),
  ('farris', 'en', 'Mineral water', 'Sparkling or still', 'Norwegian mineral water, sparkling or still, served cold with ice and lemon.', 'Mineral water, ice, lemon'),
  ('farris', 'it', 'Acqua minerale', 'Frizzante o naturale', 'Acqua minerale norvegese, frizzante o naturale, servita fredda con ghiaccio e limone.', 'Acqua minerale, ghiaccio, limone'),
  ('farris', 'zh-CN', '矿泉水', '气泡或无气', '挪威矿泉水，气泡或无气，冰镇上桌，配冰块和柠檬。', '矿泉水、冰、柠檬'),
  ('husets-ol', 'nb', 'Husets øl', 'Lokal pils fra fat, 0,4 l', 'Lys pils fra et bryggeri i nabolaget, tappet fra fat. 0,4 liter. Spør om dagens gjesteøl.', 'Vann, bygg, humle, gjær'),
  ('husets-ol', 'en', 'House beer', 'Local draught pilsner, 0.4 l', 'A pale pilsner from a brewery down the road, poured from the tap. 0.4 litres. Ask about today''s guest beer.', 'Water, barley, hops, yeast'),
  ('husets-ol', 'it', 'Birra della casa', 'Pilsner locale alla spina, 0,4 l', 'Una pilsner chiara da un birrificio vicino, spillata alla spina. 0,4 litri. Chiedi della birra ospite del giorno.', 'Acqua, orzo, luppolo, lievito'),
  ('husets-ol', 'zh-CN', '招牌啤酒', '本地生啤皮尔森，0.4 升', '来自附近酒厂的淡色皮尔森，鲜啤现打，0.4 升。可询问今日客座啤酒。', '水、大麦、啤酒花、酵母'),
  ('husets-vin', 'nb', 'Husets vin', 'Rød eller hvit, glass', 'Et glass av husets røde eller hvite. Spør hva som er åpent i dag — vi bytter etter sesong.', 'Druer, sulfitter'),
  ('husets-vin', 'en', 'House wine', 'Red or white, by the glass', 'A glass of the house red or white. Ask what''s open today — we change it with the season.', 'Grapes, sulphites'),
  ('husets-vin', 'it', 'Vino della casa', 'Rosso o bianco, al bicchiere', 'Un bicchiere di rosso o bianco della casa. Chiedi cosa è aperto oggi — cambiamo con la stagione.', 'Uva, solfiti'),
  ('husets-vin', 'zh-CN', '招牌葡萄酒', '红或白，按杯供应', '一杯招牌红葡萄酒或白葡萄酒。今天开的是哪款请询问——我们随季节更换。', '葡萄、亚硫酸盐'),
  ('varm-sjokolade', 'nb', 'Varm sjokolade', 'Mørk sjokolade, melk, krem på toppen', 'Mørk sjokolade smeltet i varm melk, med pisket krem på toppen. Ikke pulver.', 'Mørk sjokolade, melk, fløte, sukker'),
  ('varm-sjokolade', 'en', 'Hot chocolate', 'Dark chocolate, milk, cream on top', 'Dark chocolate melted into hot milk, with whipped cream on top. Not from powder.', 'Dark chocolate, milk, cream, sugar'),
  ('varm-sjokolade', 'it', 'Cioccolata calda', 'Cioccolato fondente, latte, panna', 'Cioccolato fondente sciolto nel latte caldo, con panna montata sopra. Non in polvere.', 'Cioccolato fondente, latte, panna, zucchero'),
  ('varm-sjokolade', 'zh-CN', '热巧克力', '黑巧克力、牛奶、顶部奶油', '黑巧克力融入热牛奶，顶部加打发奶油。非冲泡粉冲调。', '黑巧克力、牛奶、奶油、糖')
) as v(item_slug, locale, name, description, description_long, ingredients)
join public.items i on i.slug = v.item_slug
join public.restaurants r on r.id = i.restaurant_id and r.slug = 'sofra'
on conflict (item_id, locale) do update
  set name = excluded.name,
      description = excluded.description,
      description_long = excluded.description_long,
      ingredients = excluded.ingredients;

