-- Remove anything no longer in menu-data.mjs.
delete from public.items i
using public.restaurants r
where i.restaurant_id = r.id and r.slug = 'sofra'
  and i.slug not in ('hvitloksbrod', 'tomatsuppe', 'bruschetta', 'kyllingvinger', 'mozzarellasticks', 'rekecocktail', 'hummus-flatbrod', 'troffelpommes', 'biff-bearnaise', 'ovnsbakt-laks', 'kylling-parmesan', 'lammeskank', 'pasta-carbonara', 'fiskesuppe', 'vegetargryte', 'kjottkaker', 'margherita', 'pepperoni', 'quattro-formaggi', 'parma-rucola', 'vegetarpizza', 'kebabpizza', 'diavola', 'skogsopp-pizza', 'klassisk-burger', 'ostburger', 'baconburger', 'chiliburger', 'vegetarburger', 'kyllingburger', 'halloumiburger', 'dobbel-burger', 'cesarsalat', 'gresk-salat', 'kyllingsalat', 'rekesalat', 'quinoasalat', 'burratasalat', 'tunfisksalat', 'bete-geitost', 'sjokoladefondant', 'ostekake', 'tiramisu', 'eplekake', 'riskrem', 'isdessert', 'creme-brulee', 'brownie', 'kaffe', 'te', 'appelsinjuice', 'brus', 'farris', 'husets-ol', 'husets-vin', 'varm-sjokolade');

